<?php
require_once __DIR__.'/config/db.php';require_once __DIR__.'/config/auth.php';require_login();
$pageTitle='Orario';$active='orario';$classe=$_SESSION['classe']??'';$ruolo=$_SESSION['ruolo'];
if($ruolo==='studente'){$stmt=$pdo->prepare('SELECT o.giorno_settimana,o.ora_inizio,o.ora_fine,m.nome materia FROM orario o JOIN materie m ON m.id=o.materia_id WHERE o.classe=? ORDER BY o.giorno_settimana,o.ora_inizio');$stmt->execute([$classe]);}
else{$stmt=$pdo->prepare('SELECT o.giorno_settimana,o.ora_inizio,o.ora_fine,o.classe,m.nome materia FROM orario o JOIN materie m ON m.id=o.materia_id WHERE m.professore_id=? ORDER BY o.giorno_settimana,o.ora_inizio');$stmt->execute([$_SESSION['user_id']]);}
$rows=$stmt->fetchAll();$days=[1=>'Lunedì',2=>'Martedì',3=>'Mercoledì',4=>'Giovedì',5=>'Venerdì'];$byDay=[];foreach($rows as $r)$byDay[$r['giorno_settimana']][]=$r;
require __DIR__.'/includes/header.php';require __DIR__.'/includes/sidebar.php';?><main class="main"><header class="topbar"><h1>Orario</h1><div class="user-menu"><a href="logout.php">Esci</a></div></header><section class="content"><div class="page-head"><h2>Orario settimanale</h2><p><?= $ruolo==='studente'?'Classe '.e($classe):'Le tue lezioni assegnate' ?></p></div><div class="grid"><?php foreach($days as $num=>$label): ?><article class="card"><h3><?=$label?></h3><?php if(empty($byDay[$num])): ?><p class="empty">Nessuna lezione.</p><?php else: foreach($byDay[$num] as $r): ?><div class="msg"><strong><?=substr($r['ora_inizio'],0,5)?> - <?=substr($r['ora_fine'],0,5)?></strong><div class="meta"><?=e($r['materia'])?><?=isset($r['classe'])?' · Classe '.e($r['classe']):''?></div></div><?php endforeach;endif?></article><?php endforeach?></div></section></main><?php require __DIR__.'/includes/footer.php'; ?>